// Vanik Sense at its MVP: what each meeting decided and who owes what. Actions sit beside the minutes and are fixed in one
// click; filters look like filters; a meeting belongs to the people who were in it. Server side: sense.js.
import { S, $, esc, icon, info, chip, go, ago, api, rerender, acts, ins, toast, modal, confirmBox, menu, LOGO, navToggle, themeButton, userButton } from './core.js';
import { hint } from './hints.js';
import { welcomePage, skippedWelcome, checklist, howTo, adminPage, whoSees, transcribePrompt } from './sense_setup.js';
import { appShell, get, P } from './suite.js';
import { typeTag, blocks, spoken, insightsPage, libraryPage, integrationsPage } from './insight.js';
import { senseGuide } from './guide.js';
import { later, inScope } from './scope.js';
import { scene } from './sense_setup.js';

const loading = '<p class="muted">Loading…</p>';
const SN = { filter: 'mine', picks: [], scope: '', q: '', transcript: false, focus: false, attention: false, contact: '', ask: [], mask: {}, tq: '', tsp: '', view: 'minutes', type: '' };
const TABS = [['', 'Home'], ['meetings', 'Meetings'], ['actions', 'Actions'], ['insights', 'Insights'], ['library', 'Library'], ['ask', 'Ask'], ['settings', 'Settings']];
const day = iso => new Date(iso).toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' });
const fresh = (...s) => (s.length ? s : ['snHome', 'snTasks', 'snList', 'snMeet', 'snSet', 'snIns', 'snLib', 'snPrep', 'snSetup']).forEach(k => { P[k + 'Key'] = ''; });
const again = (...s) => { fresh(...s); rerender(); };
const sw = (on, act, label, extra = '') => `<button class="switch ${on ? 'on' : ''}" role="switch" aria-checked="${!!on}" aria-label="${esc(label)}" data-act="${act}" ${extra}></button>`;
const tog = (on, k, label) => `<button class="toggle ${on ? 'on' : ''}" data-act="sn-tog" data-k="${k}" aria-pressed="${!!on}">${label}</button>`;
const initials = n => esc(n.split(' ').map(w => w[0]).join('').slice(0, 2));

// ---------- actions: one row, everything on it
acts['sn-done'] = async el => { await api('PUT', '/api/sense/tasks/' + el.dataset.id, { status: el.dataset.on ? 'open' : 'done' }); again(); };
ins['sn-due'] = async el => { try { await api('PUT', '/api/sense/tasks/' + el.dataset.id, { due: el.value }); toast(el.value ? 'Date changed.' : 'Date removed.'); } catch (e) { toast(e.message, 'err'); } again(); };
acts['sn-owner'] = async el => { const m = await api('GET', '/api/sense/meetings/' + el.dataset.m); menu(el, [{ heading: 'From this meeting' }, ...m.people.map(p => ({ label: p.name, sub: p.email, on: p.name === el.dataset.owner, run: async () => { await api('PUT', '/api/sense/tasks/' + el.dataset.id, { owner: p.email }); toast(`${p.name} owns this now.`); again(); } }))]); };
acts['sn-confirm'] = async el => { await api('POST', `/api/sense/tasks/${el.dataset.id}/confirm`); toast('Owner confirmed.'); again(); };
acts['sn-more'] = el => { const a = JSON.parse(el.dataset.a); menu(el, [a.canNudge && { label: 'Remind the owner', icon: 'notifications_active', run: async () => { const r = await api('POST', `/api/sense/tasks/${a.id}/nudge`); toast(r.text); again(); } }, { label: 'History', icon: 'history', run: () => modal({ title: 'What changed', cancel: 'Close', body: a.trail.length ? a.trail.map(t => `<div class="set-row"><div class="grow">${esc(t.what)}<div class="small muted">${esc(t.by)}</div></div><span class="small faint">${ago(t.at)}</span></div>`).join('') : '<p class="muted">Nothing has changed since the meeting.</p>' }) }, a.canEdit && { label: 'Delete this action', icon: 'delete', danger: true, run: () => confirmBox('Delete this action?', 'Use this when the action is wrong or not needed.', 'Delete', async () => { await api('DELETE', '/api/sense/tasks/' + a.id); again(); }, true) }].filter(Boolean)); };
acts['sn-pick'] = el => { const id = el.dataset.id; SN.picks = SN.picks.includes(id) ? SN.picks.filter(x => x !== id) : [...SN.picks, id]; rerender(); };
acts['sn-bulk'] = async el => { const op = el.dataset.v, run = async due => { const r = await api('POST', '/api/sense/tasks/bulk', { ids: SN.picks, op, due }); toast(`${r.changed} changed${r.skipped ? `, ${r.skipped} skipped` : ''}.`); SN.picks = []; again(); }; if (op === 'clear') { SN.picks = []; return rerender(); } if (op === 'due') return modal({ title: 'Set a date for ' + SN.picks.length, body: '<input class="input" type="date" id="sn-bdue">', actions: [{ label: 'Set', run: o => run($('#sn-bdue', o).value) }] }); if (op === 'delete') return confirmBox(`Delete ${SN.picks.length} actions?`, 'Only the ones you may change are deleted.', 'Delete', () => run(), true); run(); };
const row = (a, where) => {
  const owner = !a.matched ? `${a.owner ? `<span class="tag" data-tip="Not in your company, so they cannot be reminded">${esc(a.owner)}, outside</span>` : '<span class="chip err">No owner</span>'}${a.suggest && a.suggest.userId && a.canEdit ? `<button class="btn ghost" style="height:26px;padding:0 10px" data-act="sn-confirm" data-id="${a.id}">${esc(a.suggest.name.split(' ')[0])}? Confirm</button>` : ''}${a.canEdit ? `<button class="btn text" style="height:26px" data-act="sn-owner" data-id="${a.id}" data-m="${a.meetingId}" data-owner="">Pick</button>` : ''}`
    : a.canEdit ? `<button class="tag" data-act="sn-owner" data-id="${a.id}" data-m="${a.meetingId}" data-owner="${esc(a.owner)}" data-tip="Change the owner">${a.mine ? 'You' : esc(a.owner)} ${icon('expand_more')}</button>` : `<span class="tag">${a.mine ? 'You' : esc(a.owner)}</span>`;
  const due = a.status === 'done' ? chip('Done', 'ok', false) : a.canEdit ? `<input class="input sn-date ${a.overdue ? 'warn' : ''}" type="date" value="${a.due}" data-change="sn-due" data-id="${a.id}" aria-label="Due date">` : chip(a.due ? day(a.due) : 'No date', a.overdue ? 'err' : '', false);
  return `<div class="set-row sn-act">${where !== 'ro' ? `<button class="icon-btn sm" data-act="sn-pick" data-id="${a.id}" aria-label="Select">${icon(SN.picks.includes(a.id) ? 'check_box' : 'check_box_outline_blank')}</button>` : ''}
    <div class="grow" style="min-width:180px"><div style="${a.status === 'done' ? 'text-decoration:line-through;opacity:.55' : ''}">${esc(a.task)}</div>${where === 'home' ? `<a class="small muted" href="#/app/sense/meetings/${a.meetingId}">${esc(a.meeting)}</a> <span class="small faint">· ${esc(a.type)}</span>` : ''}${a.overdue ? ' <span class="small" style="color:var(--vnk-err)">overdue</span>' : ''}${a.nudged ? ' <span class="small faint">reminded</span>' : ''}</div>
    <div class="row wrap" style="gap:6px;justify-content:flex-end">${owner}${due}${where !== 'ro' ? `<button class="icon-btn sm" data-act="sn-done" data-id="${a.id}" ${a.status === 'done' ? 'data-on="1"' : ''} data-tip="${a.status === 'done' ? 'Reopen' : 'Mark done'}" aria-label="Mark done">${icon(a.status === 'done' ? 'undo' : 'check_circle')}</button><button class="icon-btn sm" data-act="sn-more" data-a="${esc(JSON.stringify({ id: a.id, trail: a.trail, canEdit: a.canEdit, canNudge: a.canNudge }))}" aria-label="More">${icon('more_vert')}</button>` : ''}</div></div>`;
};
const bulkBar = () => SN.picks.length ? `<div class="banner" style="background:var(--vnk-accent-weak);color:var(--vnk-ink);margin-bottom:10px"><b>${SN.picks.length} selected</b><span class="grow"></span>${[['done', 'Mark done'], ['nudge', 'Remind'], ['due', 'Set date'], ['delete', 'Delete'], ['clear', 'Clear']].map(b => `<button class="btn ${b[0] === 'clear' ? 'text' : 'ghost'}" style="height:28px;margin:0" data-act="sn-bulk" data-v="${b[0]}">${b[1]}</button>`).join('')}</div>` : '';

// ---------- home: what you owe, what is coming, what just happened
acts['sn-filter'] = el => go('#/app/sense/actions/' + el.dataset.v);
acts['sn-intro'] = async () => { await api('POST', '/api/sense/intro'); again('snHome'); };
function home() {
  const h = get('snHome', 'h', '/api/sense/home'), st = get('snSetup', 's', '/api/sense/setup'); if (!h || !st) return loading;
  h.upcoming = h.upcoming || []; // an answer without the dashboard still draws the page
  const hr = new Date().getHours(), c = h.counts, d = h.digest, p = h.pulse || { kept: { all: null, mine: null }, week: { calls: 0, hours: 0 }, kinds: [], customers: [], pointers: [] };
  const num = (k, label, n, tone = '') => `<a class="set-row sn-num" href="#/app/sense/actions/${k}"><span class="grow">${label}</span><b class="${n && tone ? tone : ''}">${n}</b></a>`, add = `<button class="btn" data-act="sn-upload">${icon('upload_file')}Add a transcript</button>`;
  return `<h1>${hr < 12 ? 'Good morning' : hr < 17 ? 'Good afternoon' : 'Good evening'}, ${esc(h.name)}</h1><p class="sub" style="margin:8px 0 20px">${!c.meetings ? 'Nothing here yet. Your first meeting is one step away.' : c.overdue || c.week ? `You owe ${c.overdue ? `${c.overdue} overdue` : ''}${c.overdue && c.week ? ' and ' : ''}${c.week ? `${c.week} this week` : ''}.` : 'You are all caught up.'}</p>
    ${st.left ? checklist(st) : ''}
    ${transcribePrompt(h.upcoming)}
    ${!c.meetings ? noMeetings() : `<div class="sn-home"><div class="stack" style="gap:16px">
      <div class="card"><div class="card-head"><h3>Do next</h3>${info('The few things that most need you, worked out from your meetings. Each opens the place to deal with it.')}</div>${p.pointers.filter(x => inScope(x.href) && !(later('confidence') && /confidence/i.test(x.text))).length ? p.pointers.filter(x => inScope(x.href) && !(later('confidence') && /confidence/i.test(x.text))).map(x => `<div class="set-row"><span class="in-dot ${x.tone}"></span><div class="grow" style="min-width:0"><div class="lbl">${esc(x.text)}</div><div class="small muted ellipsis">${esc(x.sub)}</div></div><a class="btn ghost" href="${x.href}">${x.cta}</a></div>`).join('') : '<p class="muted">Nothing needs you right now.</p>'}</div>
      <div class="card"><div class="card-head"><h3>Latest meetings</h3><span class="grow"></span><a class="btn text" href="#/app/sense/meetings">All ${c.meetings}</a></div>${h.recent.map(m => `<a class="feed" href="#/app/sense/meetings/${m.id}"><div class="row"><div class="grow" style="min-width:0"><div class="lbl ellipsis">${esc(m.title)}</div><div class="small muted">${day(m.at)} · ${m.mins} min · ${m.participants} people</div></div>${later('kinds') ? '' : typeTag(m.type)}</div>${m.gist ? `<p class="small feed-g">${esc(m.gist)}</p>` : ''}<div class="row small"><span class="np-faces sm">${(m.faces || []).map(n => `<span class="avatar">${initials(n)}</span>`).join('')}</span><span class="grow"></span>${m.attention ? chip('Needs attention', 'warn') : ''}<span class="faint">${m.open} open ${m.open === 1 ? 'action' : 'actions'}</span></div></a>`).join('')}</div></div>
      <div class="stack" style="gap:16px">
      <div class="card"><div class="card-head"><h3>Your actions</h3><span class="grow"></span><a class="btn text" href="#/app/sense/actions">Open</a></div>${num('overdue', 'Overdue', c.overdue, 'bad')}${num('week', 'Due this week', c.week)}${num('waiting', 'Waiting on others', c.waiting)}${num('missing', 'No owner or date', c.missing, 'warn')}
        <div class="set-row sn-num"><span class="grow">Promises kept ${info('Of every promise made in your meetings, the share marked done.')}</span><b>${p.kept.all === null ? 'n/a' : p.kept.all + '%'}</b></div></div>
      ${h.upcoming.length ? `<div class="card"><div class="card-head"><h3>Coming up</h3>${info('From your calendar. Get ready opens a brief built from your earlier calls with them.')}</div>${h.upcoming.map(e => `<div class="set-row"><div class="grow" style="min-width:0"><div class="lbl ellipsis">${esc(e.title)}</div><div class="small muted">${day(e.at)}</div></div>${e.transcribe ? chip('Transcript on', 'ok') : `<button class="btn" data-act="ss-guide" data-evt="${e.id}" data-tip="Without it Sense has nothing to read">Switch on transcript</button>`}${e.known ? `<a class="btn ghost" href="#/app/sense/library/${encodeURIComponent(e.account)}">Get ready</a>` : ''}</div>`).join('')}</div>` : ''}
      ${h.team ? `<a class="card sn-team" href="#/app/sense/meetings/team"><div class="card-head"><h3>Your team</h3>${icon('chevron_right')}</div><p class="small muted">${h.team.people} ${h.team.people === 1 ? 'person reports' : 'people report'} to you. ${h.team.meetings} of their meetings are open to you${h.team.overdue ? `, and ${h.team.overdue} of their promises ${h.team.overdue === 1 ? 'is' : 'are'} overdue` : ''}.</p></a>` : ''}
      ${p.customers.length && !later('confidence') ? `<div class="card"><div class="card-head"><h3>Customers</h3><span class="grow"></span><a class="btn text" href="#/app/sense/insights">Insights</a></div>${p.customers.map(x => `<a class="set-row" href="#/app/sense/meetings/${x.id}"><div class="grow lbl">${esc(x.account)}</div>${x.score === null ? chip('Not scored', '', false) : chip(`${x.score} ${x.band}`, x.band === 'High' ? 'ok' : x.band === 'Low' ? 'err' : 'warn', false)}</a>`).join('')}</div>` : ''}
      <p class="small muted" style="margin:0 4px">${d.on ? `${icon('mail')} Daily email: ${d.overdue} overdue, ${d.tomorrow} due tomorrow.` : `${icon('notifications_off')} Daily email is off.`} <a href="#/app/sense/settings" style="text-decoration:underline">Change</a></p></div></div>`}`;
}

// ---------- actions: every action in one place
const AF = [['mine', 'Mine'], ['overdue', 'Overdue'], ['week', 'Due this week'], ['waiting', 'Waiting on others'], ['missing', 'No owner or date'], ['all', "Everyone's"], ['done', 'Done']];
function actionsPage() {
  const T = get('snTasks', SN.filter, '/api/sense/tasks?filter=' + SN.filter);
  return `<div class="row wrap" style="gap:8px;margin-bottom:16px">${AF.map(f => `<a class="toggle ${SN.filter === f[0] ? 'on' : ''}" href="#/app/sense/actions/${f[0]}">${f[1]}</a>`).join('')}</div>
    ${T && !T.length && SN.filter === 'mine' ? howTo('task_alt', 'No actions of yours are open', 'An action appears by itself after a meeting: each promise, with its owner and its date. You tick it here when it is done.', `<a class="btn ghost" href="#/app/sense/actions/all">See everyone's</a>`) : `<div class="card">${bulkBar()}${!T ? loading : T.length ? T.map(a => row(a, 'home')).join('') : '<p class="muted">Nothing here.</p>'}</div>`}`;
}

// ---------- meetings
acts['sn-tog'] = el => { SN[el.dataset.k] = !SN[el.dataset.k]; again('snList'); };
acts['sn-scope'] = el => { SN.scope = el.dataset.v; again('snList'); };
acts['sn-search'] = () => { SN.q = $('#sn-q').value; again('snList'); };
ins['sn-contact'] = el => { SN.contact = el.value; again('snList'); };
acts['sn-open'] = el => go('#/app/sense/meetings/' + el.dataset.id);
ins['sn-type-f'] = el => { SN.type = el.value; again('snList'); };
const setOff = async (id, off, scope) => { const r = await api('PUT', '/api/sense/meetings/' + id, { off, scope }); toast(off ? (r.changed > 1 ? `Transcription is off for all ${r.changed} in the series.` : 'This meeting will not be transcribed.') : 'Transcription is on.'); again(); };
acts['sn-off'] = el => { const off = !el.dataset.off; if (off && el.dataset.series) return modal({ title: 'Stop transcribing', text: 'This meeting repeats. Stop for this one, or for the whole series?', actions: [{ label: 'The whole series', run: () => setOff(el.dataset.id, true, 'all') }, { label: 'Only this one', run: () => setOff(el.dataset.id, true, 'one') }] }); setOff(el.dataset.id, off, el.dataset.series && !off ? 'all' : 'one'); };
// No meetings yet: a person either adds notes from a call they already had, or sets up so calls arrive by themselves.
const WAY_TEXT = { teams: 'Switch on transcription in Teams once, and every meeting is read when it ends.', mic: 'Press Record when a call starts. Sense listens through this computer\'s microphone.', desktop: 'The desktop app is not ready yet. Until then, record on this computer.', upload: 'Choose how calls should reach Sense: Teams by itself, or notes after each call.' };
const noMeetings = () => { const st = get('snSetup', 's', '/api/sense/setup'), k = (st && st.capture) || 'teams', src = (st && st.sources) || {}, hand = !st || st.byHand;
  return `<div class="gd-two">
    <div class="card"><span class="avatar sq">${icon('edit_note')}</span><h3>Add notes from a call</h3><p class="muted">Already had a call? Type what was decided, one point a line. Minutes, actions and owners appear in a few seconds.</p><div class="row wrap" style="gap:8px;margin-top:14px">${hand ? `<button class="btn" data-act="sn-notes">Add notes</button><button class="btn ghost" data-act="sn-upload">I have a transcript</button>` : '<span class="small muted">Your admin has switched off adding by hand.</span>'}</div></div>
    <div class="card"><span class="avatar sq">${icon('auto_awesome')}</span><h3>Have calls arrive by themselves</h3><p class="muted">${WAY_TEXT[k]}</p><div class="row wrap" style="gap:8px;margin-top:14px"><a class="btn" href="#/app/sense/guide">Follow the guide</a>${k === 'teams' ? `<button class="btn ghost" data-act="ss-guide">Switch on transcription</button>` : src.mic !== false ? `<button class="btn ghost" data-act="sn-record">${icon('mic')}Record now</button>` : ''}</div></div>
  </div><div class="card ss-empty" style="margin-top:16px">${scene(k)}</div>`; };
acts['sn-notes'] = () => modal({ title: 'Add notes from a call', wide: true, text: 'One point a line. To say who said something, start the line with their name and a colon. Promises with a name and a day become actions.',
  body: `<div class="stack" style="gap:10px"><input class="input" id="nt-t" placeholder="Name of the call, for example Site visit: Kiran Tools"><div class="row wrap" style="gap:10px"><input class="input" id="nt-d" type="date" style="width:auto" aria-label="Day of the call"><input class="input grow" id="nt-c" placeholder="Their company, if it was with a customer or a supplier"></div><input class="input" id="nt-p" placeholder="Who was there, separated by commas"><textarea class="input" id="nt-x" rows="9" placeholder="They want 500 units a month from January.&#10;Asha: I will send the revised quote by Friday.&#10;Their finance head has to approve anything above 10 lakh."></textarea></div>`,
  actions: [{ label: 'Add', run: async o => { const r = await api('POST', '/api/sense/meetings/upload', { notes: true, title: $('#nt-t', o).value, date: $('#nt-d', o).value, company: $('#nt-c', o).value, people: $('#nt-p', o).value.split(',').map(x => x.trim()).filter(Boolean), text: $('#nt-x', o).value }); toast(`Added as a ${r.type}. ${r.actions} actions found.`); fresh(); go('#/app/sense/meetings/' + r.id); } }] });
// one button for every way of adding a call by hand
acts['sn-add'] = el => { const st = P.snSetup || {}, src = st.sources || {}, hand = st.byHand !== false; menu(el, [hand && { label: 'Add notes', sub: 'Type what was decided, one point a line', icon: 'edit_note', run: () => acts['sn-notes']() }, hand && { label: 'Add a transcript', sub: 'Paste it or drop a caption file', icon: 'upload_file', run: () => acts['sn-upload']() }, src.mic !== false && { label: 'Record on this computer', sub: 'Through the microphone, for a call on speaker or in a room', icon: 'mic', run: () => acts['sn-record']() }].filter(Boolean)); };
acts['sn-upload'] = () => { const R = P.snList || { types: [] }; modal({ title: 'Add a transcript', wide: true, text: 'For a call held outside Teams: on the phone, in person, or in another tool. Put each turn on its own line as Name: what they said. A caption file works too.',
  body: `<div class="stack" style="gap:10px"><input class="input" id="su-t" placeholder="Name of the call, for example Site visit: Kiran Tools"><div class="row wrap" style="gap:10px"><input class="input" id="su-d" type="date" style="width:auto" aria-label="Day of the call"><input class="input grow" id="su-c" placeholder="Their company, if it was with a customer or a supplier">${later('kinds') ? '' : `<select class="input" id="su-k" style="width:auto" aria-label="Kind of call"><option value="">Let Vanik Sense decide the kind</option>${R.types.map(t => `<option>${esc(t)}</option>`).join('')}</select>`}</div>
    <textarea class="input" id="su-x" rows="9" placeholder="Meera Nair: We need delivery within seven days.&#10;You: We can do that from our Pune plant."></textarea><div class="row"><label class="btn ghost" style="cursor:pointer">${icon('upload_file')}Choose a file<input type="file" accept=".txt,.vtt,.srt,.md" hidden data-change="sn-upfile"></label><span class="small muted" id="su-f">Text or caption file</span></div></div>`,
  actions: [{ label: 'Add', run: async o => { const r = await api('POST', '/api/sense/meetings/upload', { title: $('#su-t', o).value, date: $('#su-d', o).value, company: $('#su-c', o).value, type: ($('#su-k', o) || {}).value || '', text: $('#su-x', o).value }); toast(`Added as a ${r.type}. ${r.actions} actions found.`); fresh(); go('#/app/sense/meetings/' + r.id); } }] }); };
ins['sn-upfile'] = el => { const f = el.files && el.files[0]; if (!f) return; const rd = new FileReader(); rd.onload = () => { const x = document.getElementById('su-x'); if (x) x.value = String(rd.result).slice(0, 400000); const n = document.getElementById('su-f'); if (n) n.textContent = f.name; const t = document.getElementById('su-t'); if (t && !t.value) t.value = f.name.replace(/\.[a-z0-9]+$/i, ''); }; rd.readAsText(f); };
function meetings() {
  const qs = new URLSearchParams({ scope: SN.scope, q: SN.q, transcript: SN.transcript ? '1' : '', focus: SN.focus ? '1' : '', attention: SN.attention ? '1' : '', contact: SN.contact, type: SN.type }).toString(), R = get('snList', qs, '/api/sense/meetings?' + qs), L = R && R.list;
  if (L && !L.length && !(SN.scope || SN.q || SN.type || SN.transcript || SN.focus || SN.attention || SN.contact)) return noMeetings();
  return `<div class="row wrap" style="gap:8px;margin-bottom:10px"><input class="input grow" id="sn-q" data-enter="sn-search" value="${esc(SN.q)}" placeholder="Search a title, a person or an action" style="min-width:220px"><div class="seg">${[['', 'All'], ['organized', 'I hosted'], ['participated', 'I joined'], ...(R && R.team ? [['team', 'My team']] : [])].map(s => `<button class="${SN.scope === s[0] ? 'on' : ''}" data-act="sn-scope" data-v="${s[0]}">${s[1]}</button>`).join('')}</div><button class="btn" data-act="sn-add">${icon('add')}Add a call</button></div>
    <div class="row wrap" style="gap:8px;margin-bottom:16px">${R && !later('kinds') ? `<select class="input" style="width:auto;height:30px" data-change="sn-type-f" aria-label="Kind of call"><option value="">Any kind of call</option>${R.types.map(t => `<option ${SN.type === t ? 'selected' : ''}>${esc(t)}</option>`).join('')}</select>` : ''}<span class="cap">Show only</span>${tog(SN.transcript, 'transcript', 'With transcript')}${tog(SN.focus, 'focus', 'Focus contacts')}${tog(SN.attention, 'attention', 'Needs attention')}${R && R.contacts.length ? `<select class="input" style="width:auto;height:30px" data-change="sn-contact" aria-label="One focus contact"><option value="">Any contact</option>${R.contacts.map(c => `<option value="${esc(c.email)}" ${SN.contact === c.email ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select>` : ''}</div>
    ${!L ? loading : !L.length ? (SN.scope || SN.q || SN.type || SN.transcript || SN.focus || SN.attention || SN.contact ? `<div class="empty">${icon('event_busy')}No meetings match. Turn a filter off.</div>` : noMeetings()) : `<div class="card" style="padding:0;overflow:auto"><table class="list"><tr><th>Meeting</th>${later('kinds') ? '' : '<th>Kind of call</th>'}<th>When</th><th>Host</th><th>Actions</th><th>Transcribe</th></tr>${L.map(m => `<tr style="cursor:pointer" data-act="sn-open" data-id="${m.id}"><td><b>${esc(m.title)}</b>${m.series ? ` <span class="tag">${esc(m.series)}</span>` : ''}${m.focus.length ? ` <span class="tag on" data-tip="Includes ${esc(m.focus.join(', '))}">Focus</span>` : ''}${m.team && m.team.length ? ` <span class="tag on" data-tip="Open to you because ${esc(m.team.join(', '))} reports to you">Team</span>` : m.readOnly ? ' <span class="tag">Forwarded to you</span>' : ''}${m.uploaded ? ` <span class="tag" data-tip="Added by hand, not from Teams">${m.fromNotes ? 'From notes' : 'Added'}</span>` : ''}<div class="small muted">${m.participants} people${m.attention ? ' · needs attention' : ''}</div></td>${later('kinds') ? '' : `<td>${typeTag(m.type)}</td>`}<td class="small">${day(m.at)}<br><span class="faint">${m.mins} min</span></td><td class="small">${m.host ? 'You' : esc(m.organizer)}</td><td>${m.on ? `${m.open} open${m.done ? `, ${m.done} done` : ''}` : chip(m.status, '', false)}</td><td>${m.host && m.status !== 'Removed' ? sw(m.on, 'sn-off', 'Transcribe this meeting', `data-stop data-id="${m.id}" ${m.on ? '' : 'data-off="1"'} ${m.series ? 'data-series="1"' : ''}`) : `<span class="small faint">${m.on ? 'On' : 'Off'}</span>`}</td></tr>`).join('')}</table></div>`}`;
}

// ---------- one meeting: minutes on the left, actions on the right
acts['sn-note'] = async el => { const t = $('#sn-note').value.trim(); if (!t) return; await api('POST', `/api/sense/meetings/${el.dataset.id}/notes`, { text: t }); again('snMeet'); };
acts['sn-forward'] = () => { const m = P.snMeet; modal({ title: 'Forward the summary', text: 'They get every key point and decision by email. The link opens this meeting read-only.', body: `<input class="input" id="sn-fwd" placeholder="name@${esc(m.domain)}">`, actions: [{ label: 'Send', run: async o => { const r = await api('POST', `/api/sense/meetings/${m.id}/forward`, { email: $('#sn-fwd', o).value }); toast(`Sent with ${r.points} points. Opens ${r.opens}.`); } }] }); };
acts['sn-view'] = el => { SN.view = el.dataset.v; rerender(); };
acts['sn-type'] = el => { const m = P.snMeet; menu(el, [{ heading: 'What kind of call was this?' }, ...m.types.map(t => ({ label: t, on: t === m.type, run: async () => { await api('PUT', '/api/sense/meetings/' + m.id, { type: t }); toast('Changed. The insights follow.'); again('snMeet', 'snList', 'snIns', 'snTasks'); } }))]); };
acts['sn-send'] = el => { const m = P.snMeet, c = k => m.connections.find(x => x.key === k), post = async to => { try { const r = await api('POST', `/api/sense/meetings/${m.id}/send`, { to }); toast(r.text + '.'); } catch (e) { toast(e.message, 'err'); } };
  menu(el, [{ label: 'Forward by email', sub: 'Opens read-only for a colleague', icon: 'forward_to_inbox', run: () => acts['sn-forward']() }, m.canSend && c('teams') && c('teams').on && { label: 'Post in the Teams chat', sub: 'Of this meeting', icon: 'groups', run: () => post('teams') },
    m.canSend && c('slack') && { label: 'Post to Slack', sub: c('slack').on ? c('slack').channel || 'Name a channel in Settings first' : 'Connect Slack in Settings first', icon: 'tag', run: () => (c('slack').on && c('slack').channel ? post('slack') : go('#/app/sense/settings')) }].filter(Boolean)); };
acts['sn-menu'] = el => { const m = P.snMeet, mine = m.people.filter(p => p.userId && !p.host); menu(el, [{ label: 'Add someone who should have been here', icon: 'person_add', run: () => modal({ title: 'Add a participant', text: 'They can then be given actions.', body: '<div class="stack" style="gap:10px"><input class="input" id="sn-pn" placeholder="Name"><input class="input" id="sn-pe" placeholder="Work email"></div>', actions: [{ label: 'Add', run: async o => { await api('POST', `/api/sense/meetings/${m.id}/participants`, { name: $('#sn-pn', o).value, email: $('#sn-pe', o).value }); again('snMeet'); } }] }) },
  m.host && { label: 'Who can change actions', icon: 'edit', run: () => modal({ title: 'Who can change actions?', body: `<div class="stack" style="gap:10px">${[['host', 'Only me'], ['owners', 'Each owner, their own'], ['all', 'Everyone in the meeting']].map(x => `<label class="row" style="gap:10px"><input type="radio" name="sn-er" value="${x[0]}" ${m.editRights === x[0] ? 'checked' : ''}><span>${x[1]}</span></label>`).join('')}</div>`, actions: [{ label: 'Save', run: async o => { await api('PUT', '/api/sense/meetings/' + m.id, { editRights: o.querySelector('input[name=sn-er]:checked').value }); again('snMeet'); } }] }) },
  m.host && { label: 'Who can delete the minutes', icon: 'shield', run: () => modal({ title: 'Who can delete the minutes?', text: 'You always can. Tick anyone else.', body: `<div class="stack" style="gap:10px">${mine.map(p => `<label class="row" style="gap:10px"><input type="checkbox" value="${p.userId}" ${m.deleters.includes(p.userId) ? 'checked' : ''}><span>${esc(p.name)}</span></label>`).join('') || '<p class="muted">Nobody else from your company was in this meeting.</p>'}</div>`, actions: [{ label: 'Save', run: async o => { await api('PUT', '/api/sense/meetings/' + m.id, { deleters: [...o.querySelectorAll('input:checked')].map(i => i.value) }); again('snMeet'); } }] }) },
  m.canDelete && { label: 'Delete the minutes', icon: 'delete', danger: true, run: () => confirmBox('Delete the minutes?', 'The minutes, transcript and actions are removed for everyone. This cannot be undone.', 'Delete', async () => { await api('DELETE', `/api/sense/meetings/${m.id}/summary`); again(); }, true) }].filter(Boolean)); };
// ---------- one meeting, laid out as a notepad: the notes on the left, the transcript beside them
const HUE = ['#4f7cff', '#e0802f', '#2fa56b', '#a560d6', '#d6534f', '#1f9fb3', '#b8961f', '#7d8590'];
const hue = (m, who) => HUE[Math.max(0, m.pad.talk.findIndex(x => x.who === who)) % HUE.length];
const SMART = [['q', 'Questions', 'help_outline', 'questions'], ['task', 'Promises', 'task_alt', 'tasks'], ['date', 'Dates', 'event', 'dates'], ['num', 'Numbers', 'tag', 'nums']];
const READY = ['What was decided?', 'What do I owe, and by when?', 'What did they ask for?', 'What is still open?'];
Object.assign(SN, { tab: 'summary', tf: '', tq: '', tsp: '', forId: '' });
const shown = m => m.transcript.map((l, i) => ({ l, i, f: m.pad.flags[i] || {} })).filter(x => (!SN.tsp || x.l.who === SN.tsp) && (!SN.tq || x.l.text.toLowerCase().includes(SN.tq.toLowerCase())) && (!SN.tf || (SN.tf === 'hl' ? m.highlights.includes(x.i) : SN.tf.startsWith('tr:') ? (x.f.tr || []).includes(SN.tf.slice(3)) : x.f[SN.tf])));
const lineHtml = (m, x) => { const on = m.highlights.includes(x.i); return `<div class="tl ${on ? 'hl' : ''}" id="tl-${x.i}"><span class="avatar" style="background:${hue(m, x.l.who)};color:#fff">${initials(x.l.who)}</span><div class="grow"><div class="small"><b>${esc(x.l.who)}</b> <span class="faint mono">${esc(x.l.t)}</span>${x.f.q ? icon('help_outline', 'tl-f') : ''}${x.f.task ? icon('task_alt', 'tl-f') : ''}</div><div>${esc(x.l.text)}</div></div>${m.readOnly || m.via ? '' : `<button class="icon-btn sm tl-star" data-act="sn-hl" data-i="${x.i}" data-tip="${on ? 'Remove the mark' : 'Mark this line to find it again'}" aria-label="Mark this line">${icon(on ? 'star' : 'star_border')}</button>`}</div>`; };
const linesHtml = m => { const L = shown(m); return L.length ? L.map(x => lineHtml(m, x)).join('') : '<p class="muted" style="padding:14px">No lines match.</p>'; };
ins['sn-tq'] = el => { SN[el.dataset.k] = el.value; const box = $('#sn-lines'); if (box) box.innerHTML = linesHtml(P.snMeet); };
acts['sn-tf'] = el => { SN.tf = SN.tf === el.dataset.v ? '' : el.dataset.v; rerender(); };
acts['sn-tab'] = el => { SN.tab = el.dataset.v; rerender(); };
// from a point in the notes to its line in the transcript
acts['sn-jump'] = el => { const go2 = () => { const t = $('#tl-' + el.dataset.i); if (t) { t.scrollIntoView({ block: 'center', behavior: 'smooth' }); t.classList.add('flash'); setTimeout(() => t.classList.remove('flash'), 1800); } }; if (SN.tf || SN.tq || SN.tsp) { SN.tf = ''; SN.tq = ''; SN.tsp = ''; rerender(); setTimeout(go2, 60); } else go2(); };
acts['sn-hl'] = async el => { const m = P.snMeet, i = +el.dataset.i; try { const r = await api('POST', `/api/sense/meetings/${m.id}/highlights`, { i }); m.highlights = r.on ? [...m.highlights, i] : m.highlights.filter(x => x !== i); } catch (e) { return toast(e.message, 'err'); } const box = $('#sn-lines'), top = box ? box.scrollTop : 0; rerender(); const nb = $('#sn-lines'); if (nb) nb.scrollTop = top; };
const minutesText = m => [`# ${m.title}`, `${day(m.at)} · ${m.mins} min · ${m.people.map(p => p.name).join(', ')}`, '', '## Summary', m.summary.overall, '', '## Key points', ...(m.summary.points.length ? m.summary.points.map(p => '- ' + p) : ['None picked out.']), '', '## Decisions', ...(m.summary.decisions.length ? m.summary.decisions.map(p => '- ' + p) : ['None recorded.']), '', '## Actions', ...(m.actions.length ? m.actions.map(x => `- [${x.status === 'done' ? 'x' : ' '}] ${x.task}${x.owner ? ` (${x.owner}${x.due ? ', by ' + x.due : ''})` : ''}`) : ['None.'])].join('\n');
const save = (name, text) => { const u = URL.createObjectURL(new Blob([text], { type: 'text/plain;charset=utf-8' })), l = document.createElement('a'); l.href = u; l.download = name; l.click(); setTimeout(() => URL.revokeObjectURL(u), 2000); };
acts['sn-export'] = el => { const m = P.snMeet, file = m.title.replace(/[^\w]+/g, '-').replace(/^-|-$/g, '').slice(0, 60) || 'meeting';
  menu(el, [{ label: 'Copy the summary', icon: 'content_copy', run: async () => { try { await navigator.clipboard.writeText(minutesText(m)); toast('Copied.'); } catch { toast('The browser did not allow copying.', 'err'); } } }, { label: 'Download the minutes', sub: 'Summary, decisions and actions, as text', icon: 'description', run: () => save(file + '-minutes.md', minutesText(m)) },
    m.transcript.length && { label: 'Download the transcript', sub: 'Every line with its speaker and time', icon: 'notes', run: () => save(file + '-transcript.txt', m.transcript.map(l => `${l.t ? '[' + l.t + '] ' : ''}${l.who}: ${l.text}`).join('\n')) }].filter(Boolean)); };
acts['sn-ready'] = el => { const q = $('#sn-mq'); if (q) q.value = el.dataset.q; return acts['sn-mask']({ dataset: { id: P.snMeet.id } }); };
acts['sn-mask'] = async el => { const id = el.dataset.id, q = $('#sn-mq').value.trim(); if (!q) return; SN.mask[id] = { q, a: null }; rerender(); try { SN.mask[id].a = await api('POST', '/api/sense/ask', { q, meetingId: id }); } catch (e) { SN.mask[id].a = { answer: e.message, sources: [] }; } rerender(); };
function meeting(id) {
  const m = get('snMeet', id, '/api/sense/meetings/' + id); if (!m) return loading;
  if (SN.forId !== id) Object.assign(SN, { forId: id, tab: 'summary', tf: '', tq: '', tsp: '' });
  const s = m.summary, ro = m.readOnly, ans = SN.mask[id], pad = m.pad, hasT = !!pad && m.transcript.length > 0, tab = SN.tab === 'insights' && (ro || !m.insight) ? 'summary' : SN.tab;
  const sec = (t, body, extra = '') => `<div class="np-sec"><div class="np-h"><h4>${t}</h4>${extra}</div>${body}</div>`;
  const li = (ic, list, none) => list.length ? list.map(p => `<div class="row small" style="margin-bottom:8px;align-items:flex-start">${icon(ic)}<span>${esc(p)}</span></div>`).join('') : `<p class="muted small">${none}</p>`;
  const marks = hasT ? m.highlights.slice().sort((x, y) => x - y) : [];
  const summary = () => `${sec('Overview', `<p>${esc(s.overall)}</p>${pad && pad.keywords.length ? `<div class="row wrap" style="gap:6px;margin-top:10px">${pad.keywords.map(k => `<span class="tag">${esc(k)}</span>`).join('')}</div>` : ''}`)}
      ${marks.length ? sec('Marked lines', marks.map(i => `<button class="np-mark" data-act="sn-jump" data-i="${i}">${icon('star')}<span><b>${esc(m.transcript[i].who.split(' ')[0])}</b> ${esc(m.transcript[i].text)}</span></button>`).join('')) : ''}
      ${pad && pad.outline.length ? sec('Outline', pad.outline.map(c => `<div class="np-ch"><button class="np-t" data-act="sn-jump" data-i="${c.i}">${c.t ? `<span class="mono">${esc(c.t)}</span>` : icon('chevron_right')}<b>${esc(c.title)}</b></button>${c.bullets.map(x => `<button class="np-b" data-act="sn-jump" data-i="${x.i}">${esc(x.text)}</button>`).join('')}</div>`).join(''), info('The meeting in order, cut into parts. Each line opens its place in the transcript.')) : ''}
      ${sec('Key points', li('chevron_right', s.points, 'None picked out.'))}${sec('Decisions', li('gavel', s.decisions, 'None recorded.'))}
      ${m.links.length ? sec('Shared in the chat', m.links.map(l => `<div class="set-row">${icon(l.kind === 'file' ? 'description' : 'link')}<div class="grow"><div class="lbl">${esc(l.title)}</div><div class="small muted">${esc(l.by)} · ${l.t}</div></div></div>`).join('')) : ''}`;
  const actions = () => `${ro ? '' : bulkBar()}${m.actions.length ? m.actions.map(x => row(x, ro ? 'ro' : 'meet')).join('') : '<p class="muted">No actions came out of this meeting.</p>'}`;
  const people = () => `${pad && pad.talk.length ? sec('Talk time', pad.talk.map(x => `<div class="np-talk"><span class="avatar" style="background:${hue(m, x.who)};color:#fff">${initials(x.who)}</span><div class="grow"><div class="row small"><b class="grow ellipsis">${esc(x.who)}</b><span class="mono">${x.pct}%</span></div><div class="meter"><i style="width:${x.pct}%;background:${hue(m, x.who)}"></i></div><div class="small faint">${x.words} words · ${x.turns} ${x.turns === 1 ? 'turn' : 'turns'} · ${x.questions} ${x.questions === 1 ? 'question' : 'questions'} · longest ${x.longest} words</div></div></div>`).join(''), info('Each person\'s share of the words said. The sound is not kept, so words are the measure.')) : ''}
      ${sec('People', m.people.map(p => `<div class="set-row"><span class="avatar">${initials(p.name)}</span><div class="grow"><div class="lbl">${esc(p.name)}</div><div class="small muted">${esc(p.email)}</div></div>${p.host ? chip('Host', '', false) : ''}${p.focus ? chip('Focus', 'warn', false) : ''}${p.added ? chip('Added later', '', false) : ''}</div>`).join('') + (m.seenBy && m.seenBy.length ? `<p class="small muted" style="margin-top:10px">${icon('supervisor_account')} Also open, read-only, to ${esc(m.seenBy.join(', '))}, under your company's rule.</p>` : ''))}
      ${ro ? '' : sec(`Your notes ${info('Only you can see these.')}`, `${m.notes.map(n => `<div class="set-row"><div class="grow" style="white-space:pre-wrap">${esc(n.text)}</div><span class="small faint">${ago(n.at)}</span></div>`).join('')}<textarea class="input" id="sn-note" rows="2" style="margin-top:8px" placeholder="Something decided after the meeting, or to raise next time"></textarea><button class="btn ghost" style="margin-top:8px" data-act="sn-note" data-id="${m.id}">Add note</button>`)}`;
  const TABS = [['summary', 'Summary'], ['actions', `Actions${m.open ? ` <span class="mono">${m.open}</span>` : ''}`], ...(!ro && m.insight && !later('kinds') ? [['insights', 'Insights']] : []), ['people', 'People']];
  const strip = hasT && pad.timeline.length > 1 ? `<div class="np-strip" data-tip="Who spoke when. Press a part to go to it.">${pad.timeline.map(x => `<button style="flex:${x.w};background:${hue(m, x.who)}" data-act="sn-jump" data-i="${x.i}" aria-label="${esc(x.who)} ${esc(x.t)}"></button>`).join('')}</div><div class="np-legend">${pad.talk.map(x => `<span><i style="background:${hue(m, x.who)}"></i>${esc(x.who.split(' ')[0])} ${x.pct}%</span>`).join('')}</div>` : '';
  const chipF = (v, label, ic, n) => `<button class="toggle ${SN.tf === v ? 'on' : ''}" data-act="sn-tf" data-v="${v}" aria-pressed="${SN.tf === v}">${ic ? icon(ic) : ''}${label}${n !== undefined ? ` <span class="mono">${n}</span>` : ''}</button>`;
  const transcript = hasT ? `<div class="card np-tr"><div class="np-h" style="margin-bottom:8px"><h4>Transcript</h4><span class="small muted">${m.transcript.length} lines</span></div>
      <div class="row wrap" style="gap:8px;margin-bottom:8px"><input class="input grow" data-on="sn-tq" data-k="tq" value="${esc(SN.tq)}" placeholder="Search the transcript" style="min-width:150px" aria-label="Search the transcript"><select class="input" style="width:auto" data-change="sn-tq" data-k="tsp" aria-label="One speaker"><option value="">Everyone</option>${pad.talk.map(x => `<option ${SN.tsp === x.who ? 'selected' : ''}>${esc(x.who)}</option>`).join('')}</select></div>
      <div class="row wrap np-filters">${SMART.filter(f => pad.counts[f[3]]).map(f => chipF(f[0], f[1], f[2], pad.counts[f[3]])).join('')}${marks.length ? chipF('hl', 'Marked', 'star', marks.length) : ''}${pad.tracked.map(t => chipF('tr:' + t.id, esc(t.name), '', t.count)).join('')}</div>
      <div id="sn-lines" class="np-lines">${linesHtml(m)}</div></div>` : '';
  return `<a class="back" href="#/app/sense/meetings">${icon('arrow_back')}Meetings</a>${m.via === 'team' ? `<div class="banner" style="margin-bottom:14px">${icon('supervisor_account')}You can read this because ${esc(m.teamOf.join(', '))} ${m.teamOf.length === 1 ? 'reports' : 'report'} to you. ${{ actions: 'You see the actions only.', minutes: 'You see the minutes and actions, not the transcript.', transcript: '' }[m.detail]} Your opening it is recorded.</div>` : ro ? `<div class="banner" style="margin-bottom:14px">${icon('visibility')}This summary was forwarded to you. You can read it. You cannot change it.</div>` : ''}
    <div class="page-head np-head"><div class="grow" style="min-width:0"><h1>${esc(m.title)}</h1><p class="sub">${later('kinds') ? '' : m.host && !ro ? `<button class="tag in-type" data-act="sn-type" data-tip="${esc((m.insight || {}).why || 'Set by the host')}. Change">${esc(m.type)} ${icon('expand_more')}</button>` : typeTag(m.type)} ${day(m.at)} · ${m.mins} min · Host: ${esc(m.organizer)}${m.series ? ' · ' + esc(m.series) : ''}${m.fromNotes ? ' · from notes' : ''}</p></div>
      <div class="np-faces" data-tip="${esc(m.people.map(p => p.name).join(', '))}">${m.people.slice(0, 5).map(p => `<span class="avatar">${initials(p.name)}</span>`).join('')}${m.people.length > 5 ? `<span class="avatar">+${m.people.length - 5}</span>` : ''}</div>
      ${s ? `<button class="btn ghost" data-act="sn-export">${icon('download')}Export</button>` : ''}${!ro && m.on ? `<button class="btn" data-act="sn-send">${icon('share')}Share</button>` : ''}${!ro ? `<button class="icon-btn" data-act="sn-menu" aria-label="More">${icon('more_vert')}</button>` : ''}</div>
    ${!s ? `<div class="empty">${icon('visibility_off')}${m.status === 'Removed' ? 'The minutes of this meeting were deleted.' : 'This meeting was not transcribed.'}${!ro && m.status !== 'Removed' ? `<br><button class="btn" data-act="sn-notes">${icon('edit_note')}Add notes from a call</button>` : ''}</div>` : `
    ${strip}
    ${ro && !hasT ? '' : `<div class="card np-ask"><div class="row" style="gap:8px">${icon('auto_awesome')}<input class="input grow" id="sn-mq" data-enter="sn-mask" data-id="${id}" value="${ans ? esc(ans.q) : ''}" placeholder="Ask about this meeting" aria-label="Ask about this meeting"><button class="btn ghost" data-act="sn-mask" data-id="${id}">Ask</button></div>
      ${ans ? (ans.a ? `<p style="margin:12px 0 0">${esc(ans.a.answer)}</p>${ans.a.sources.map(x => `<span class="tag" style="margin:8px 6px 0 0">${esc(x.who)} ${x.t}</span>`).join('')}` : loading) : `<div class="row wrap" style="gap:6px;margin-top:10px">${READY.map(q => `<button class="tag" data-act="sn-ready" data-q="${esc(q)}">${esc(q)}</button>`).join('')}</div>`}</div>`}
    <div class="${hasT ? 'np' : 'np one'}"><div class="card np-notes"><div class="np-tabs">${TABS.map(t => `<button class="${tab === t[0] ? 'on' : ''}" data-act="sn-tab" data-v="${t[0]}">${t[1]}</button>`).join('')}</div>
      ${tab === 'actions' ? actions() : tab === 'insights' ? `<div class="stack" style="gap:16px">${blocks(m.insight.blocks, m.id)}${spoken(m.insight)}</div>` : tab === 'people' ? people() : summary()}</div>${transcript}</div>`}`;
}

// ---------- ask, settings
acts['sn-ask'] = async () => { const el = $('#sn-ask'), q = el.value.trim(); if (!q) return; SN.ask.push({ q, a: null }); rerender(); try { SN.ask[SN.ask.length - 1].a = await api('POST', '/api/sense/ask', { q }); } catch (e) { SN.ask[SN.ask.length - 1].a = { answer: e.message, sources: [] }; } rerender(); };
acts['sn-notif'] = async () => { await api('PUT', '/api/sense/settings', { notifications: !P.snSet.notifications }); again('snSet', 'snHome'); };
acts['sn-focus-add'] = () => modal({ title: 'Add a focus contact', text: 'Meetings with this person are marked for you, and you can filter by them. Only you see your list.', body: '<div class="stack" style="gap:10px"><input class="input" id="sf-n" placeholder="Name"><input class="input" id="sf-e" placeholder="Email"></div>', actions: [{ label: 'Add', run: async o => { await api('POST', '/api/sense/focus', { name: $('#sf-n', o).value, email: $('#sf-e', o).value }); again(); } }] });
acts['sn-focus-del'] = async el => { await api('DELETE', '/api/sense/focus/' + el.dataset.id); again(); };
const NAV = [['', 'Home', 'home'], ['meetings', 'Meetings', 'event_note'], ['actions', 'Actions', 'task_alt'], ['insights', 'Insights', 'insights'], ['library', 'Library', 'bookmarks'], ['ask', 'Ask', 'forum'], ['integrations', 'Integrations', 'extension']];
const TITLE = { '': 'Home', meetings: 'Meetings', actions: 'Actions', insights: 'Insights', library: 'Library', ask: 'Ask', settings: 'Settings', admin: 'Admin', guide: 'Guide', integrations: 'Integrations' };
// one box in the top bar: a question goes to Ask, anything else searches the meetings
acts['sn-find'] = async () => { const el = $('#sn-find'), v = el ? el.value.trim() : ''; if (!v) return; el.value = '';
  if (/\?$|^(what|who|whom|when|where|why|how|did|does|do|is|are|was|were|can|could|should|which)\b/i.test(v)) { SN.ask.push({ q: v, a: null }); go('#/app/sense/ask'); rerender(); try { SN.ask[SN.ask.length - 1].a = await api('POST', '/api/sense/ask', { q: v }); } catch (e) { SN.ask[SN.ask.length - 1].a = { answer: e.message, sources: [] }; } return rerender(); }
  SN.q = v; fresh('snList'); go('#/app/sense/meetings'); rerender(); };
acts['sn-apps'] = el => { const B = S.boot, to = (label, ic, href) => ({ label, icon: ic, run: () => go(href) }); menu(el, [{ heading: 'Your other apps' }, B.canUseGpt && to('VanikGPT', 'forum', '#/gpt'), ...B.suite.apps.filter(a => a.canUse && a.id !== 'sense').map(a => to(a.name, a.icon, '#/app/' + a.id)), '-', to('All my apps', 'apps', '#/me'), B.admin && to('Vanik Edge console', 'dns', '#/os/home')].filter(Boolean)); };
// Vanik Sense is a product of its own: its pages are its menu. Other apps sit behind one button.
function shell(tab, body) {
  const B = S.boot, me = B.suite.apps.find(a => a.id === 'sense') || {}, st0 = P.snSetup, adm = !!st0 && st0.canAdmin && st0.runBy.length > 0, item = (k, label, ic) => `<a class="nav-item ${tab === k ? 'is-active' : ''}" href="#/app/sense${k ? '/' + k : ''}">${icon(ic)}<span>${label}</span></a>`;
  return `<div class="shell"><aside class="console-nav"><a class="brand" href="#/app/sense">${LOGO}<span class="vk-brand"><small>Vanik Edge</small><b>Sense</b></span></a>
    ${NAV.map(n => item(n[0], n[1], n[2])).join('')}<span class="grow"></span>${adm ? item('admin', 'Admin', 'admin_panel_settings') : ''}${item('guide', 'Guide', 'menu_book')}${item('settings', 'Settings', 'settings')}<button class="nav-item" data-act="sn-apps">${icon('apps')}<span>Other apps</span></button></aside>
    <div class="main"><header class="topbar">${navToggle()}<span class="crumb"><b>${TITLE[tab] || 'Home'}</b></span>${hint('sense')}<input class="input sn-find" id="sn-find" data-enter="sn-find" placeholder="Search meetings, or ask a question" aria-label="Search meetings, or ask a question"><span class="right"></span><button class="btn" data-act="sn-add">${icon('add')}Capture</button>${themeButton()}${userButton()}</header><div class="scroll" id="scroll"><div class="page">${body}</div></div></div></div>`;
}
export function sensePage(tab = '', id) {
  const st = get('snSetup', 's', '/api/sense/setup');
  if (tab === 'welcome' || (st && !st.steps[0].done && !skippedWelcome())) return welcomePage(); // a first-time person answers four questions before anything else
  if (!TITLE[tab]) tab = '';
  if (tab === 'meetings' && id === 'team') { if (SN.scope !== 'team') { SN.scope = 'team'; fresh('snList'); } id = ''; }
  let body;
  if (tab === 'meetings') body = id ? meeting(id) : meetings();
  else if (tab === 'admin') body = adminPage(id);
  else if (tab === 'guide') body = st ? senseGuide(st) : loading;
  else if (tab === 'integrations') { const s = get('snSet', 's', '/api/sense/settings'); body = s ? integrationsPage(s) : loading; }
  else if (tab === 'ask') body = `<div class="card" style="max-width:820px">${SN.ask.length ? SN.ask.map(c => `<div style="margin-bottom:18px"><p><b>${esc(c.q)}</b></p>${!c.a ? loading : `<p style="margin-top:6px">${esc(c.a.answer)}</p>${c.a.sources.map(s => `<a class="tag" style="margin:8px 6px 0 0" href="#/app/sense/meetings/${s.meetingId}">${esc(s.meeting)} · ${esc(s.who)} ${s.t}</a>`).join('')}`}</div>`).join('') : '<p class="muted">Ask across every meeting you were in. Each answer shows the lines it came from.</p>'}<div class="row" style="gap:8px;margin-top:12px"><input class="input grow" id="sn-ask" data-enter="sn-ask" placeholder="What did we promise the supplier?"><button class="btn" data-act="sn-ask">Ask</button></div></div>`;
  else if (tab === 'settings') { const s = get('snSet', 's', '/api/sense/settings'); body = !s || !st ? loading : `<div class="stack" style="gap:16px;max-width:720px">${whoSees(st)}<div class="card"><div class="set-row"><div class="grow"><div class="lbl">Daily email</div><div class="small muted">One email each morning: overdue, due tomorrow, due this week. No tone, no rating.</div></div>${sw(s.notifications, 'sn-notif', 'Daily email')}</div>
      <div class="set-row"><div class="grow"><div class="lbl">Transcription</div><div class="small muted">On for your meetings. The host can switch a meeting off from the Meetings list.</div></div><a class="btn ghost" href="#/app/sense/meetings">Meetings</a></div></div>
      <div class="card"><div class="card-head"><h3>Focus contacts</h3>${info('Meetings with these people are marked for you. Only you see your list.')}<span class="grow"></span><button class="btn ghost" data-act="sn-focus-add">${icon('add')}Add</button></div>${s.focus.length ? s.focus.map(f => `<div class="set-row"><div class="grow"><div class="lbl">${esc(f.name)}</div><div class="small muted">${esc(f.email)}</div></div><button class="btn text" data-act="sn-focus-del" data-id="${f.id}">Remove</button></div>`).join('') : '<p class="muted">Nobody yet.</p>'}</div>
      <a class="card sn-team" href="#/app/sense/integrations"><div class="card-head"><h3>Integrations</h3>${icon('chevron_right')}</div><p class="small muted">${s.connections.filter(c => c.on).length} of ${s.connections.length} connected: ${esc(s.connections.filter(c => c.on).map(c => c.name).join(', ') || 'none yet')}.</p></a>
      <div class="card"><div class="set-row"><div class="grow"><div class="lbl">How you work</div><div class="small muted">Your kind of work, your role and how meetings reach Vanik Sense.</div></div><a class="btn ghost" href="#/app/sense/welcome">Change</a></div></div></div>`; }
  else if (tab === 'actions') { if (id && AF.some(f => f[0] === id) && SN.filter !== id) { SN.filter = id; SN.picks = []; fresh('snTasks'); } body = actionsPage(); }
  else if (tab === 'insights') body = insightsPage();
  else if (tab === 'library') body = libraryPage(id || '');
  else body = home();
  return shell(tab, body);
}
